schuldverschreibung_zahlungssperre_intervall <- function(antrag_zahlungssperre_am=NULL, zahlungssperre_vor_verfahrenseinleitung=NULL, sechsmonatsfrist_letzter_tag=NULL, einleitungsantrag_am=NULL, verfahren_erledigt_am=NULL, beobachtung_bis=NULL, einordnungsnachweis=NULL) {
 a <- .datum(antrag_zahlungssperre_am,'antrag_zahlungssperre_am');b <- .datum(beobachtung_bis,'beobachtung_bis');vor <- .wahrheitswert(zahlungssperre_vor_verfahrenseinleitung,'zahlungssperre_vor_verfahrenseinleitung');.text(einordnungsnachweis,'einordnungsnachweis')
 if(b<a) .fehler('beobachtung_bis','Beobachtung nicht vor Beginn.')
 if(!vor && !is.null(sechsmonatsfrist_letzter_tag)) .fehler('sechsmonatsfrist_letzter_tag','Ohne Vorverfahren keine unber\u00fccksichtigte Fristangabe.')
 frist <- if(vor) .datum(sechsmonatsfrist_letzter_tag,'sechsmonatsfrist_letzter_tag') else NULL
 if(!is.null(frist) && frist<a) .fehler('sechsmonatsfrist_letzter_tag','F\u00fcr diesen qualifizierten Ablauf Fristende nicht vor Hemmungsbeginn.')
 einleitung <- if(is.null(einleitungsantrag_am)) NULL else .datum(einleitungsantrag_am,'einleitungsantrag_am');erledigung <- if(is.null(verfahren_erledigt_am)) NULL else .datum(verfahren_erledigt_am,'verfahren_erledigt_am')
 if(!is.null(einleitung) && einleitung>b) .fehler('einleitungsantrag_am','Tats\u00e4chliches Ereignis nicht nach Beobachtung.')
 if(!is.null(erledigung) && (erledigung<a || erledigung>b)) .fehler('verfahren_erledigt_am','Erledigung zwischen Hemmungsbeginn und Beobachtung erforderlich.')
 ende <- erledigung
 if(vor && frist<=b && (is.null(einleitung)||einleitung>frist)) ende <- if(is.null(ende)) frist else min(ende,frist)
 wert <- list(feststehendes_hemmungsende=if(is.null(ende)) NULL else format(ende,'%Y-%m-%d'),hemmung_bis_beobachtung_abgeschlossen=!is.null(ende),hemmungszeitraeume=list(list(erster_gehemmter_tag=format(a,'%Y-%m-%d'),letzter_gehemmter_tag=format(if(is.null(ende))b else ende,'%Y-%m-%d'))))
 eingaben <- list(antrag_zahlungssperre_am=antrag_zahlungssperre_am, zahlungssperre_vor_verfahrenseinleitung=zahlungssperre_vor_verfahrenseinleitung, sechsmonatsfrist_letzter_tag=sechsmonatsfrist_letzter_tag, einleitungsantrag_am=einleitungsantrag_am, verfahren_erledigt_am=verfahren_erledigt_am, beobachtung_bis=beobachtung_bis, einordnungsnachweis=einordnungsnachweis)
 ergebnis <- .ergebnis(wert,"daten_und_intervalle","BGB_SCHULDVERSCHREIBUNG_ZAHLUNGSSPERRE_INTERVALL",eingaben,list(list(operation="Tats\u00e4chliche Erledigung und gegebenenfalls unwahrte Sechsmonatsfrist vergleichen; fr\u00fchestes bekanntes Hemmungsende oder ausdr\u00fccklich begrenztes Beobachtungsintervall bilden.")),eingaben)
 ergebnis$hinweise <- list("802: Beginn mit Zahlungssperrenantrag. Ende mit tats\u00e4chlicher Verfahrenserledigung; im qualifizierten Vorverfahren zus\u00e4tzlich Ablauf der korrigierten Sechsmonatsfrist, sofern bis dahin kein wirksamer Einleitungsantrag gestellt war. Fr\u00fcheres Endereignis ma\u00dfgeblich. Einleitungsantrag am letzten Fristtag wahrt; sp\u00e4terer Antrag belebt bereits beendete Hemmung nicht r\u00fcckwirkend wieder. Bei laufender Hemmung nur bis Beobachtung rechnen und Abschluss ausdr\u00fccklich verneinen. Keine k\u00fcnstliche Verfahrenserledigung. Hemmung beeinflusst auch Beginn der Vorlegungsfrist; entsprechende Weiterrechnung mit209unter rechtlicher Qualifikation und ohne doppelte Tage. Sechsmonatsgrundfrist/206/210/211werden vorgelagert mit vorhandenen Kernen berechnet. Datumstage sind rechtlich normalisierte eingeschlossene Hemmungstage; untert\u00e4gige Sonderf\u00e4lle nicht pauschal runden.")
 ergebnis
}
